function resolveExecutable(
    candidates
) {

    for (
        const candidate
        of candidates.filter(Boolean)
    ) {

        /*
         * Absolute/local paths can be
         * verified directly.
         */
        if (
            candidate.includes("\\") ||
            candidate.includes("/")
        ) {

            if (
                fs.existsSync(
                    candidate
                )
            ) {
                return candidate;
            }

            continue;
        }


        /*
         * Bare executable names are kept
         * as a final PATH fallback.
         */
        return candidate;
    }


    return null;
}


function spawnDetached(
    executable,
    args = []
) {

    return new Promise(
        (
            resolve,
            reject
        ) => {

            const child =
                spawn(
                    executable,
                    args,
                    {
                        detached: true,
                        stdio: "ignore",
                        windowsHide: true
                    }
                );


            child.once(
                "error",
                reject
            );


            child.once(
                "spawn",
                () => {

                    child.unref();

                    resolve();
                }
            );
        }
    );
}


function focusWindowsApplication(
    processName
) {

    if (
        process.platform !== "win32"
    ) {
        return Promise.resolve(false);
    }


    const safeName =
        String(processName)
            .replaceAll(
                "'",
                "''"
            );


    const script = `
$p = Get-Process -Name '${safeName}' -ErrorAction SilentlyContinue |
    Where-Object { $_.MainWindowHandle -ne 0 } |
    Select-Object -First 1

if (-not $p) {
    exit 1
}

$wshell = New-Object -ComObject WScript.Shell

if ($wshell.AppActivate($p.Id)) {
    exit 0
}

exit 2
`;


    return new Promise(
        resolve => {

            const child =
                spawn(
                    "powershell.exe",
                    [
                        "-NoProfile",
                        "-NonInteractive",
                        "-WindowStyle",
                        "Hidden",
                        "-Command",
                        script
                    ],
                    {
                        windowsHide: true,
                        stdio: "ignore"
                    }
                );


            child.once(
                "error",
                () =>
                    resolve(false)
            );


            child.once(
                "close",
                code =>
                    resolve(
                        code === 0
                    )
            );
        }
    );
}

function projectFileTitle(
    file
) {

    if (
        !(file instanceof TFile)
    ) {
        return "";
    }


    return (
        file.extension === "md"
            ? file.basename
            : file.name
    );
}


